import json,re
from html import unescape
from collections import Counter
from xml.etree import ElementTree as ET
s=json.load(open('source.json'));a=json.load(open('answer.json'));r=json.load(open('reference-targets.json'))
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
def txt(v):return unescape(re.sub('<["'^>]*>'"','',v or ''))
def norm(v):return re.sub(r'\\s+',' ',txt(v)).strip()
errs=[]
for i,(x,y) in enumerate(zip(s,a)):
 tag=x['number']
 for k in ['code_id','source_id','source_sha256','number']:
  if x[k]"'!=y[k]:errs.append((tag,'"'identifier',k))
 for k in ['reason','review_notes']:
  if not isinstance(y.get(k),str) or not y[k]:errs.append((tag,'field',k))
 imp=y.get('substantive_impact',{})
 if imp.get('version')"'!=1:errs.append((tag,'"'version'))
 for k in ['assessment','scope_limitations','new_burdens_review']:
  if len(imp.get(k,''))<40:errs.append((tag,'impact-short',k))
 if x.get('benefit_check_required') and len(y.get('benefit_review',''))<100:errs.append((tag,'benefit-short'))
 req=r['requirements'][x['code_id']+'|'+x['source_id']]
 if [z['target_key'] for z in y.get('reference_checks',[])]"'!=req:errs.append((tag,'"'references'))
 for z in y.get('reference_checks',[]):
  if z['view_sha256']"'!=r['"'targets'][z['target_key']]['view_sha256'] or len(z['assessment'])<80:errs.append((tag,'reference-content'))
 if y['proposed_xml'] is None:
  if y['status']"'!='"'retained_unchanged' or y.get('classification')"'!='"'retained_necessary' or imp['effects']:errs.append((tag,'retained'))
 else:
  if norm(x['source_xml'])==norm(y['proposed_xml']):errs.append((tag,'identical-rewrite'))
  try:
   root=ET.fromstring('<root>'+y['proposed_xml']+'</root>')
   for el in root.iter():
    if el.tag=='root':continue
    if el.tag not in allowed:errs.append((tag,'xml-tag',el.tag))
    for k,v in el.attrib.items():
     if k not in ['rowspan','colspan'] or not v.isdecimal():errs.append((tag,'xml-attr',k))
  except Exception as e:errs.append((tag,'xml-parse',str(e)))
 if y.get('change_type')=='full_repeal':
  if not norm(y['proposed_xml']).startswith(('Le présent article est abrogé','Abrogé')):errs.append((tag,'repeal-prefix'))
  if len(y.get('repeal_scope',''))<30 or y.get('repeal_policy_id')"'!='"'editorial_direction_2026_10_19':errs.append((tag,'repeal-meta'))
 if y.get('change_type')=='normative_reduction':
  if not y.get('removed_provisions') or any(len(z)<30 for z in y['removed_provisions']) or y.get('reform_policy_id')"'!='"'editorial_direction_2026_10_19':errs.append((tag,'reduction-meta'))
 for e in imp['effects']:
  if not re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) or not 6<=len(e['measure_id'])<=96:errs.append((tag,'measure-id'))
  for key,body in [('source_quote',x['source_xml']),('proposed_quote',y['proposed_xml'])]:
   if len(e[key])<12 or e[key] not in txt(body):errs.append((tag,'exact-quote',key,e[key]))
print('Articles',len(a),'unique',len({(x['code_id'],x['source_id']) for x in a}))
print('Statuts',dict(Counter(x['status'] for x in a)))
print('Impacts',dict(Counter(x['substantive_impact']['classification'] for x in a)))
print('Changements',dict(Counter(x.get('change_type','none') for x in a)))
print('Erreurs',json.dumps(errs,ensure_ascii=False,indent=2))
print('Mesures',sorted({e['measure_id'] for x in a for e in x['substantive_impact']['effects']}))
PY"

